begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(1);
set local app.tenant_id='00000000-0000-7000-8000-000000000001';
do $$ declare i uuid;r uuid;person uuid;work uuid;artifact uuid;doc uuid;version uuid;rep uuid;node uuid;procedure uuid;chunkset uuid;chunk uuid;
begin
 if not exists(select 1 from retrieval.chunk_entity_mention m join retrieval.chunk_span s on s.chunk_id=m.chunk_id join content.document_node n on n.id=s.document_node_id where m.entity_id=person and n.start_ms=1000 and n.end_ms=2000) then raise exception 'media coordinates lost through chunks';end if;
 if(select count(*) from corpus.media_appearance where media_work_id=work and role='speaker')<>1 then raise exception 'speaker appearance missing';end if;
 set constraints all immediate;
end $$;
select pass('knowledge_model_media invariants hold');
select * from finish();
rollback;
